from queueing import payload

def submit(owner, enqueue, batch_size=20):
    # Validate batch_size before enqueue
    # Reject bool and invalid values
    if batch_size is True or batch_size is False:
        raise ValueError("batch_size must be an integer between 1 and 100, not a bool")
    if not isinstance(batch_size, int):
        raise ValueError("batch_size must be an integer between 1 and 100")
    if batch_size < 1 or batch_size > 100:
        raise ValueError("batch_size must be an integer between 1 and 100")

    # Create payload with batch_size
    payload_data = payload(owner, batch_size=20 if batch_size is None else batch_size)
    return enqueue(payload_data)

def execute(task, process):
    batch_size = task.get("batch_size", 20)
    return process(task["owner"], batch_size)
